const body = $input.first().json.body || $input.first().json;
if (!body.jobTitles || (Array.isArray(body.jobTitles) && body.jobTitles.length === 0) || (typeof body.jobTitles === 'string' && body.jobTitles.trim() === '')) {
  throw new Error('Validation failed: jobTitles is required and must not be empty.');
}
return [{ json: {
    jobTitles:       Array.isArray(body.jobTitles)       ? body.jobTitles       : (body.jobTitles ? [body.jobTitles] : []),
    industryIds:     Array.isArray(body.industryIds)     ? body.industryIds     : (body.industryIds ? [body.industryIds] : []),
    geoIds:          Array.isArray(body.geoIds)          ? body.geoIds          : (body.geoIds ? [body.geoIds] : ['103644278']),
    workplaceType:   Array.isArray(body.workplaceType)   ? body.workplaceType   : ['office', 'hybrid'],
    employmentType:  Array.isArray(body.employmentType)  ? body.employmentType  : ['full-time'],
    experienceLevel: Array.isArray(body.experienceLevel) ? body.experienceLevel : ['mid-senior', 'director'],
    postedLimit:     body.postedLimit  || '24h',
    maxItems:        body.maxItems     || 100,
    sortBy:          body.sortBy       || 'date',
    under10Applicants: body.under10Applicants === true ? true : false,
  }
}];

const p = $('Extract Search Params').first().json;
return [{ json: {
    actor_input: {
      industryIds: p.industryIds, jobTitles: p.jobTitles, geoIds: p.geoIds,
      workplaceType: p.workplaceType, employmentType: p.employmentType,
      experienceLevel: p.experienceLevel, postedLimit: p.postedLimit,
      maxItems: p.maxItems, sortBy: p.sortBy, under10Applicants: p.under10Applicants,
    },
    search_summary: `${p.jobTitles.join(', ')} | ${p.postedLimit}`
  }
}];

