const allRuns = $('Count Today Runs').all();
const existingRunsToday = allRuns.filter(r => r.json && r.json.run_id).length;
const sequence = existingRunsToday + 1;
const meta = $('Extract Run Meta').first().json;
function ordinal(n) { const s = ['th','st','nd','rd']; const v = n % 100; return n + (s[(v-20)%10] || s[v] || s[0]); }
const runLabel = `${meta.run_date} Run ${sequence} (${ordinal(sequence)} run of day)`;
return [{ json: { ...meta, run_sequence_of_day: sequence, run_label: runLabel } }];

const items = $input.all();
return items.map(item => {
  const d=item.json, company=d.company||{}, hiringTeam=Array.isArray(d.hiringTeam)?d.hiringTeam:[], recruiter=hiringTeam[0]||{}, applyMethod=d.applyMethod||{};
  const jobUrn=String(d.id||d.jobId||'').trim(), jobId=jobUrn.includes(':')?jobUrn.split(':').pop():jobUrn;
  const jobUrl=d.url||d.linkedinUrl||(jobId?`https://www.linkedin.com/jobs/view/${jobId}`:'');
  let applicantCount=0; const rawAppl=d.applicants;
  if(typeof rawAppl==='number') applicantCount=rawAppl;
  else if(typeof rawAppl==='string'){const m=rawAppl.match(/\d+/); applicantCount=m?parseInt(m[0]):0;}
  const range=company.employeeCountRange||{}; let companySizeStr='';
  if(range.end===null||range.end===undefined) companySizeStr=range.start?'10,001+ employees':'';
  else if(range.start!=null&&range.end!=null) companySizeStr=`${range.start.toLocaleString()}-${range.end.toLocaleString()} employees`;
  const industriesArr=(Array.isArray(d.industries)&&d.industries.length>0)?d.industries:(Array.isArray(company.industries)?company.industries:[]);
  const industryLabel=industriesArr.length>0?(typeof industriesArr[0]==='string'?industriesArr[0]:(industriesArr[0].name||industriesArr[0].title||'')): '';
  const companyLocs=Array.isArray(company.locations)?company.locations:[], hq=companyLocs[0]||{};
  const companyLocality=[hq.city,hq.geographicArea,hq.country].filter(Boolean).join(', ');
  const companyProfile=company.linkedinUrl||(company.universalName?`https://www.linkedin.com/company/${company.universalName}`:'')||(company.id?`https://www.linkedin.com/company/${company.id}`:'');
  const jobLocation=typeof d.location==='string'?d.location:[d.location?.city,d.location?.state,d.location?.country].filter(Boolean).join(', ');
  let postedDatetime=null; try{const rawDate=d.postedAt||d.postedDate||d.listedAt; postedDatetime=rawDate?new Date(rawDate).toISOString():new Date().toISOString();}catch(e){postedDatetime=new Date().toISOString();}
  const salaryObj=d.salary||d.salaryInfo||{}; let baseSalary=null;
  if(salaryObj.min!=null&&salaryObj.max!=null) baseSalary=`${salaryObj.currency||'$'}${salaryObj.min}\u2013${salaryObj.max} ${salaryObj.period||''}`.trim();
  else if(salaryObj.text) baseSalary=salaryObj.text;
  const applyUrl=applyMethod.companyApplyUrl||applyMethod.easyApplyUrl||jobUrl;
  const recruiterName=recruiter.name||recruiter.fullName||null, recruiterProfile=recruiter.profileUrl||recruiter.linkedinUrl||null, recruiterDetail=recruiter.headline||recruiter.title||null;
  let companyDomain=''; const websiteRaw=company.website||'';
  if(websiteRaw){try{const urlObj=new URL(websiteRaw.startsWith('http')?websiteRaw:`https://${websiteRaw}`); companyDomain=urlObj.hostname.replace(/^www\./,'');}catch(e){companyDomain=websiteRaw.replace(/^https?:\/\//,'').replace(/^www\./,'').split('/')[0];}}
  return{json:{job_urn:jobUrn,job_id:jobId,job_url:jobUrl,title:d.title||'',location:jobLocation,posted_datetime:postedDatetime,description_text:d.description||d.descriptionText||'',seniority_level:d.seniorityLevel||d.experienceLevel||'',employment_type:d.employmentType||'',base_salary:baseSalary,apply_url:applyUrl,applicants_count:applicantCount,applicants:applicantCount===0?'':`${applicantCount} applicants`,company_id:String(company.id||'').trim(),company_name:company.name||'',company_profile:companyProfile,company_website:company.website||'',company_domain:companyDomain,company_size:companySizeStr,company_locality:companyLocality,company_industry:industryLabel,company_description:company.description||null,company_founded:company.founded||null,company_followers:company.followerCount||null,employeeCountRange:company.employeeCountRange||null,employeeCount:company.employeeCount||null,industries:industriesArr,recruiter_name:recruiterName,recruiter_detail:recruiterDetail,recruiter_profile:recruiterProfile,hiring_team_count:hiringTeam.length}};
});

const staffingKeywords=['staffing','recruiting','recruitment','headhunter','talent acquisition','talent solutions','talent agency','executive search','placement agency','manpower','workforce solutions','contract staffing','temp agency','temporary staffing','contingent workforce','outsourcing','hr solutions','hr services','people solutions','search firm','hiring solutions','staff augmentation','contract hire','direct hire','perm placement'];
const columnsToCheck=['title','company_name','location','company_industry','company_locality','company_size'];
function isGarbageOrNonEnglish(str){if(!str||typeof str!=='string')return false; const cleaned=str.trim(); if(!cleaned)return false; if(/[\u3000-\u9fff\uac00-\ud7af\uf900-\ufaff]/.test(cleaned))return true; if(/[\u0400-\u04ff\u0600-\u06ff\u0900-\u097f\u0e00-\u0e7f\u05d0-\u05ea]/.test(cleaned))return true; const nonAscii=(cleaned.match(/[^\x00-\x7f]/g)||[]).length; if(nonAscii/cleaned.length>0.3)return true; const words=cleaned.split(/\s+/); const gibberishWords=words.filter(w=>{if(w.length<5)return false; const letters=w.replace(/[^a-zA-Z]/g,''); if(letters.length<4)return false; const vowels=(letters.match(/[aeiouAEIOU]/g)||[]).length; return vowels/letters.length<0.1;}); if(gibberishWords.length>0)return true; const specialChars=(cleaned.match(/[^a-zA-Z0-9\s.,\-'&()\/!?@#%:]/g)||[]).length; if(specialChars/cleaned.length>0.25)return true; return false;}
const allItems=$input.all(), filteredItems=[], skippedItems=[];
allItems.forEach(item=>{const company=(item.json.company_name||'').toLowerCase(); const hasStaffingKeyword=staffingKeywords.some(kw=>company.includes(kw)); if(hasStaffingKeyword){skippedItems.push({company:item.json.company_name,title:item.json.title,skip_reason:'Staffing keyword',bad_value:item.json.company_name}); return;} let skipped=false; for(const col of columnsToCheck){if(isGarbageOrNonEnglish(item.json[col])){skippedItems.push({company:item.json.company_name,title:item.json.title,skip_reason:`Non-English: "${col}"`,bad_value:item.json[col]}); skipped=true; break;}} if(!skipped)filteredItems.push(item);});
const result=filteredItems.map(item=>({...item,json:{...item.json,_skipped_nonenglish_count:skippedItems.length,_skipped_nonenglish_rows:skippedItems}}));
console.log(`Non-English filter: ${allItems.length} -> ${filteredItems.length}`);
return result;

const MAX_APPLICANTS=30, allItems=$input.all(), filteredItems=[], skippedItems=[];
allItems.forEach(item=>{const count=item.json.applicants_count||0; if(!item.json.applicants){filteredItems.push(item);return;} if(count<=MAX_APPLICANTS) filteredItems.push(item); else skippedItems.push({company:item.json.company_name,title:item.json.title,skip_reason:`Too many applicants (${count})`,bad_value:count});});
const result=filteredItems.map(item=>({...item,json:{...item.json,_skipped_applicant_count:skippedItems.length,_skipped_applicant_rows:skippedItems}}));
console.log(`Applicants filter (max ${MAX_APPLICANTS}): ${allItems.length} -> ${filteredItems.length}`);
return result;

let supabaseRows=[];
try{supabaseRows=$('Get many rows').all();}catch(e){supabaseRows=[];}
const existingCompanyIds=new Set(supabaseRows.map(row=>String(row.json.company_uid||'').trim()).filter(id=>id&&id!=='undefined'&&id!=='null'));
const batchCompanyIds=new Map(), allItems=$input.all(), uniqueItems=[];
allItems.forEach(item=>{const companyId=String(item.json.company_id||'').trim(); if(!companyId){console.log(`Skipped - missing company_id: ${item.json.company_name}`);return;} if(existingCompanyIds.has(companyId)){console.log(`Duplicate (Supabase): ${item.json.company_name}`);return;} if(batchCompanyIds.has(companyId)){console.log(`Duplicate (batch): ${item.json.company_name}`);return;} batchCompanyIds.set(companyId,{company:item.json.company_name,title:item.json.title}); uniqueItems.push(item);});
console.log(`Deduplication: ${allItems.length} -> ${uniqueItems.length}`);
return uniqueItems;

const MAX_EMPLOYEES=500, items=$input.all();
const filteredItems=items.filter(item=>{const range=item.json.employeeCountRange; if(range&&typeof range==='object'){if(range.end===null||range.end===undefined){console.log(`Excluded [10001+]: ${item.json.company_name}`);return false;} const passes=range.end<MAX_EMPLOYEES; if(!passes)console.log(`Excluded [range ${range.start}-${range.end}]: ${item.json.company_name}`); return passes;} if(typeof item.json.employeeCount==='number'&&item.json.employeeCount>0){const passes=item.json.employeeCount<MAX_EMPLOYEES; if(!passes)console.log(`Excluded [count ${item.json.employeeCount}]: ${item.json.company_name}`); return passes;} console.log(`No size data (kept): ${item.json.company_name}`); return true;});
console.log(`Company size filter: ${items.length} -> ${filteredItems.length}`);
return filteredItems;

const excludedIndustries=['staffing and recruiting','staffing','recruiting','human resources','hr services','it services','it consulting','software development','technology, information and internet','government administration','gambling','advertising services','education','non-profit organizations','non-profit organization management','non-profit','dairy','restaurants','hospitality','resorts','hotels','bars','pubs','breweries','wine and spirits','tourism','travel','leisure','sports','casinos','performing arts','music','photography','newspapers','museums','institutions','government relations','public policy','international affairs','non-profit organization','charity','foundations','fundraising','e-learning','universities','higher education','primary education','secondary education','professional training','coaching','computer security','network security','computer hardware','computer networking','management consulting','market research','executive search','investment banking','investment management','military','security and investigations','aviation','aerospace','airlines','defence','space','maritime','shipbuilding','mental healthcare','veterinary','individual and family services','luxury goods','jewelry','cosmetics','tobacco','executive office','writing','editing','event services','programme development','libraries'];
const items=$input.all();
const filteredItems=items.filter(item=>{const industriesArray=item.json.industries; if(Array.isArray(industriesArray)&&industriesArray.length>0){for(const ind of industriesArray){const val=typeof ind==='string'?ind.toLowerCase():[(ind.name||''),(ind.title||''),(ind.hierarchy||'')].join(' ').toLowerCase(); const isExcluded=excludedIndustries.some(term=>val.includes(term)); if(isExcluded){console.log(`Excluded: ${item.json.company_name} -> "${val}"`);return false;}} return true;} const industry=(item.json.company_industry||'').toLowerCase(); const isExcluded=excludedIndustries.some(term=>industry.includes(term)); if(isExcluded)console.log(`Excluded [fallback]: ${item.json.company_name} -> "${industry}"`); return!isExcluded;});
console.log(`Industry filter: ${items.length} -> ${filteredItems.length}`);
return filteredItems;

return $input.all().map(item=>{
  const data=item.json;
  const jobUrl=data.job_url||`https://www.linkedin.com/jobs/view/${data.job_id}`;
  const companyUrl=data.company_profile||`https://www.linkedin.com/company/${data.company_id}`;
  let industryStr=data.company_industry||''; if(!industryStr&&Array.isArray(data.industries)&&data.industries.length>0){const first=data.industries[0]; industryStr=typeof first==='string'?first:(first.name||first.title||'');}
  const runMeta=$('Build Run Tag').first().json;
  return{json:{'Job title':data.title,'Job ID':data.job_id,'job url':jobUrl,'location':data.location,'company name':data.company_name,'company ID':data.company_id,'company profile':companyUrl,'company website':data.company_website||null,'company domain':data.company_domain||null,'company size':data.company_size||null,'company location':data.company_locality||null,'industry':industryStr,'posted time':data.posted_datetime||null,'applicants':data.applicants_count||0,'base salary':data.base_salary||null,'seniority level':data.seniority_level||null,'employment type':data.employment_type||null,'job description':data.description_text||null,'apply url':data.apply_url||jobUrl,'recruiter_name':data.recruiter_name||null,'recruiter_details':data.recruiter_detail||null,'recruiter_profile':data.recruiter_profile||null,'hiring_team_count':data.hiring_team_count||0,'run_id':runMeta.run_id,'run_label':runMeta.run_label}};
});
